@Component("office-entity-projector")
public class OfficeEntityProjector implements EntityProjector<Office>{
		
	// core constructor
	public OfficeEntityProjector(ProjectorRegistry registry,
										OfficeRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Office> getEntityClass() {
		return Office.class;
	}

    /*
	 * Insert a Office
	 * 
     * @param	entity Office
     */
    public Office create( Office entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Office
	 * 
     * @param	entity Office
     */
    public Office update( Office entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Office
	 * 
     * @param	id		UUID
     */
    public Office delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Office entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Firm
     * 
     * @param	parentId	UUID
     * @param	assignment 	WealthFirm 
     * @return	Office
     */
    public Office assignFirm( UUID parentId, WealthFirm assignment ) {
	    LOGGER.info("assigning Firm as " + assignment.toString() );

	    Office parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( WealthFirm.class, assignment.getWealthFirmId());

	    // ------------------------------------------
		// assign the Firm to the parent entity
		// ------------------------------------------ 
	    parentEntity.setFirm( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Firm
	 * 
	 * @param	parentId		UUID
	 * @return	Office
	 */
	public Office unAssignFirm( UUID parentId ) {
		Office parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Firm on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Firm on the parent entithy
		// ------------------------------------------     
	    parentEntity.setFirm(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Advisors
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Office
     */
    public Office addToAdvisors( UUID parentId, Advisor addTo ) {
	    LOGGER.info("handling AssignAdvisorsToOfficeEvent - " );
	    
	    Office parentEntity = repository.findById(parentId).get();
	    Advisor child = registry.project( Advisor.class, addTo.getAdvisorId());
	    
	    parentEntity.getAdvisors().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Advisors
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Office
     */
	public Office removeFromAdvisors( UUID parentId, Advisor removeFrom ) {
	    LOGGER.info("handling RemoveAdvisorsFromOfficeEvent " );
	
	    Office parentEntity = repository.findById(parentId).get();
	    Advisor child = registry.project( Advisor.class, removeFrom.getAdvisorId());
	    
	    parentEntity.getAdvisors().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Office via an FindOfficeQuery
     * @return 	query	FindOfficeQuery
     */
    @SuppressWarnings("unused")
    public Office find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Office - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Offices
     *
     * @param	query	FindAllOfficeQuery 
     * @return 	List<Office> 
     */
    @SuppressWarnings("unused")
    public List<Office> findAll( FindAllOfficeQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Office - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final OfficeRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(OfficeEntityProjector.class.getName());

}
